def peer_share(self, i: int, adopt_flags: List[int]) -> float:
    neigh = self.neighbors[i]
    if not neigh:
        return sum(adopt_flags) / max(1, len(adopt_flags))
    s = sum(adopt_flags[j] for j in neigh)
    return s / max(1, len(neigh))
